package br.com.pelotavision;
import static org.junit.Assert.*;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import android.graphics.*;import java.io.*;import java.nio.file.*;import java.util.*;import org.json.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=33,manifest=Config.NONE) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class EllipseWorkflowTest {
 static PelletDetector.Detection ellipse(double x,double y,double a,double b,double angle,boolean partial,boolean review){PelletDetector.Detection seed=new PelletDetector.Detection(x,y,Math.sqrt(a*b),Math.PI*a*b,1,partial,review);return new PelletDetector.Detection(seed,x,y,a,b,angle,true,.9,.02,partial,review);}
 static PelletDetector.Result result(PelletDetector.Detection... ds){return new PelletDetector.Result(Arrays.asList(ds),380,300,ds.length,1,false,"gradient_circle_CLAHE_v1+ellipse_boundary_v1");}
 @Test public void shapeMeanIsByNumberAndExcludesUnknownPartialAndReview()throws Exception{
  PelletDetector.Result r=result(ellipse(90,100,60,30,0,false,false),ellipse(210,100,15,15,0,false,false),ellipse(0,100,40,25,0,true,false),ellipse(300,100,40,30,0,false,true),new PelletDetector.Detection(120,200,20,Math.PI*400,1,false,false));ShapeStatistics shape=ShapeStatistics.of(r);assertEquals(2,shape.included);assertEquals(3,shape.excluded);assertEquals(.75,shape.mean,1e-12);
  JSONObject json=ResultSaver.shapeJson(r);assertFalse(json.getBoolean("true_3d_sphericity"));assertEquals(.75,json.getDouble("mean"),1e-12);assertEquals("ellipse_minor_major_axis_ratio",json.getString("metric"));
  PelletDetector.Result empty=result();assertTrue(Double.isNaN(ShapeStatistics.of(empty).mean));assertTrue(ResultSaver.shapeJson(empty).isNull("mean"));
 }
 @Test public void rotatedEllipseIsUsedForRectangularAndCircularRoi(){
  PelletDetector.Detection d=ellipse(100,100,60,20,45,false,false);double extent=Math.sqrt(2000);assertEquals(extent,d.extentX(),1e-10);assertTrue(new InterestRegion(InterestRegion.Shape.RECTANGLE,100-extent,100-extent,100+extent,100+extent).includes(d));assertFalse(new InterestRegion(InterestRegion.Shape.RECTANGLE,60,60,140,140).includes(d));assertTrue(d.normalizedDistance(d.boundaryX(.3),d.boundaryY(.3))<=1+1e-10);
  Random random=new Random(31);for(int k=0;k<40;k++){d=ellipse(100,100,25+random.nextDouble()*50,10+random.nextDouble()*10,random.nextDouble()*180,false,false);double cx=60+random.nextDouble()*80,cy=60+random.nextDouble()*80,max=0;for(int j=0;j<8192;j++)max=Math.max(max,Math.hypot(d.boundaryX(2*Math.PI*j/8192)-cx,d.boundaryY(2*Math.PI*j/8192)-cy));double actual=d.farthestDistance(cx,cy);assertTrue(actual>=max-1e-7);assertEquals(max,actual,.001);if(cx-actual>=0&&cy-actual>=0){InterestRegion roi=new InterestRegion(InterestRegion.Shape.CIRCLE,cx-actual,cy-actual,cx+actual,cy+actual);assertTrue(roi.includes(d));}}
 }
 @Test public void savedCompositionDrawsRotatedEllipseAndPreservesOriginal(){
  Bitmap photo=Bitmap.createBitmap(380,300,Bitmap.Config.ARGB_8888);photo.eraseColor(Color.rgb(50,60,70));PelletDetector.Detection d=ellipse(190,150,60,20,30,false,false);Bitmap composed=PhotoComposer.compose(photo,result(d),null);PhotoComposer.Layout layout=new PhotoComposer.Layout(380,300);int x=(int)Math.round(d.boundaryX(0)),y=(int)Math.round(d.boundaryY(0))+layout.annotatedTop;boolean green=false;
  for(int dy=-2;dy<=2;dy++)for(int dx=-2;dx<=2;dx++){int c=composed.getPixel(x+dx,y+dy);if(Color.green(c)>190&&Color.red(c)<120)green=true;}assertTrue("Major-axis endpoint must be drawn outside the former equivalent circle",green);
  for(int yy=0;yy<300;yy+=13)for(int xx=0;xx<380;xx+=13)assertEquals(photo.getPixel(xx,yy),composed.getPixel(xx,layout.originalTop+yy));assertEquals(Color.rgb(16,26,35),composed.getPixel(2,layout.histogramTop+2));photo.recycle();composed.recycle();
 }
 @Test public void actualSaverExportsEllipseAxesMeanEquivalentDiameterAndCalibration()throws Exception{
  android.content.Context context=RuntimeEnvironment.getApplication();File root=new File(context.getCacheDir(),"ellipse_export");root.mkdirs();CrackExportTest.FakeMediaStore provider=new CrackExportTest.FakeMediaStore(root);android.content.pm.ProviderInfo info=new android.content.pm.ProviderInfo();info.authority="media";provider.attachInfo(context,info);org.robolectric.shadows.ShadowContentResolver.registerProviderInternal("media",provider);
  Bitmap photo=Bitmap.createBitmap(380,300,Bitmap.Config.ARGB_8888);photo.eraseColor(Color.GRAY);File source=new File(root,"input.png");try(FileOutputStream out=new FileOutputStream(source)){assertTrue(photo.compress(Bitmap.CompressFormat.PNG,100,out));}
  PelletDetector.Detection d=ellipse(190,150,60,30,30,false,false);PelletDetector.Result r=result(d);Granulometry.Distribution distribution=Granulometry.compute(Arrays.asList(new Granulometry.Item(2*d.radius,false,false)),new Granulometry.Settings(20,1,true,true),760,600,380,300);
  ResultSaver.SavedResult saved=ResultSaver.save(context,photo,source,"image/png",r,PelletDetector.Parameters.automatic(),null,distribution);JSONObject json=new JSONObject(new String(Files.readAllBytes(new File(root,saved.base+".json").toPath()),java.nio.charset.StandardCharsets.UTF_8));JSONObject object=json.getJSONArray("detections").getJSONObject(0);assertEquals(120,object.getDouble("ellipse_major_axis_px"),0);assertEquals(60,object.getDouble("ellipse_minor_axis_px"),0);assertEquals(12,object.getDouble("ellipse_major_axis_mm"),1e-10);assertEquals(6,object.getDouble("ellipse_minor_axis_mm"),1e-10);assertEquals(2*Math.sqrt(1800)/10,object.getDouble("equivalent_diameter_mm"),1e-10);assertEquals(.5,json.getJSONObject("shape_analysis").getDouble("mean"),0);
  String[] row=Files.readAllLines(new File(root,saved.base+".csv").toPath()).get(1).split(";",-1);assertEquals(32,row.length);assertEquals("120.000000",row[16]);assertEquals("0.500000",row[19]);assertEquals("12.000000",row[22]);assertTrue(json.getJSONObject("histogram").getString("diameter_method").startsWith("ellipse_equivalent"));assertArrayEquals(Files.readAllBytes(source.toPath()),Files.readAllBytes(new File(root,saved.base+"_original.png").toPath()));photo.recycle();
 }
 @Test public void providedScenesRenderNewEllipseReportsAndMeanMatchesNative()throws Exception{
  File root=new File(System.getProperty("pelotavision.validationDir")),dir=new File(root,"ellipse-0.6.0");
  for(String scene:new String[]{"brown40","gray42","gray20","dense","cluster","spaced","paired40"}){
   JSONObject input=new JSONObject(new String(Files.readAllBytes(new File(dir,scene+"_analysis.json").toPath()),java.nio.charset.StandardCharsets.UTF_8));Bitmap photo=BitmapFactory.decodeFile(new File(root.getParentFile(),"ml_training/data/"+scene+".png").getAbsolutePath());assertNotNull(photo);List<PelletDetector.Detection> objects=new ArrayList<>();List<CrackAnalysis.Entry> entries=new ArrayList<>();JSONArray ds=input.getJSONArray("detections");
   for(int i=0;i<ds.length();i++){JSONObject o=ds.getJSONObject(i);PelletDetector.Detection seed=new PelletDetector.Detection(o.getDouble("crack_x"),o.getDouble("crack_y"),o.getDouble("crack_radius"),Math.PI*Math.pow(o.getDouble("crack_radius"),2),1,o.getBoolean("partial"),o.getBoolean("crack_review"));objects.add(new PelletDetector.Detection(seed,o.getDouble("x"),o.getDouble("y"),o.getDouble("semi_major"),o.getDouble("semi_minor"),o.getDouble("angle"),o.getBoolean("fitted"),o.isNull("support")?Double.NaN:o.getDouble("support"),o.isNull("rms")?Double.NaN:o.getDouble("rms"),o.getBoolean("partial"),o.getBoolean("review")));JSONArray a=o.getJSONArray("runs");float[] runs=new float[a.length()];for(int j=0;j<runs.length;j++)runs[j]=(float)a.getDouble(j);entries.add(new CrackAnalysis.Entry(i+1,CrackAnalysis.Status.valueOf(o.getString("status")),runs,o.getDouble("score"),CrackModel.ID));}
   PelletDetector.Result r=new PelletDetector.Result(objects,photo.getWidth(),photo.getHeight(),objects.size(),0,false,input.getString("method"));ShapeStatistics shape=ShapeStatistics.of(r);assertEquals(input.getInt("included"),shape.included);assertEquals(input.getDouble("mean"),shape.mean,1e-9);CrackAnalysis c=new CrackAnalysis(r.width,r.height,50,0,entries);Bitmap report=PhotoComposer.compose(photo,r,c,null);ByteArrayOutputStream encoded=new ByteArrayOutputStream();assertTrue(report.compress(Bitmap.CompressFormat.PNG,100,encoded));byte[] bytes=encoded.toByteArray();assertArrayEquals(new byte[]{73,69,78,68},Arrays.copyOfRange(bytes,bytes.length-8,bytes.length-4));File outputDir=new File(root,"reference-0.7.0/scenes");outputDir.mkdirs();File target=new File(outputDir,scene+"_report.png"),temporary=new File(outputDir,scene+"_report.tmp");Files.write(temporary.toPath(),bytes);Files.move(temporary.toPath(),target.toPath(),StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);assertArrayEquals(bytes,Files.readAllBytes(target.toPath()));report.recycle();photo.recycle();
  }
 }
}
